import"./style-vm8_bK0d.js";const m=document.getElementById("word-input"),e=document.getElementById("find-btn"),a=document.getElementById("results"),o=document.getElementById("synonyms-list"),i=document.getElementById("antonyms-section"),c=document.getElementById("antonyms-list"),r=document.getElementById("error-msg");async function l(){const n=m.value.trim();if(n){a.classList.add("hidden"),r.classList.add("hidden"),i.classList.add("hidden"),o.innerHTML="",c.innerHTML="",e.disabled=!0,e.textContent="Searching...";try{const t=await(await fetch(`https://api.datamuse.com/words?rel_syn=${n}`)).json(),s=await(await fetch(`https://api.datamuse.com/words?rel_ant=${n}`)).json();if(t.length===0&&s.length===0)throw new Error("No words found.");t.length>0?o.innerHTML=t.slice(0,15).map(d=>`<span style="background: var(--bg); border: 1px solid var(--border); padding: 0.25rem 0.5rem; border-radius: 0.25rem;">${d.word}</span>`).join(""):o.innerHTML="<p>No synonyms found.</p>",s.length>0&&(i.classList.remove("hidden"),c.innerHTML=s.slice(0,15).map(d=>`<span style="background: var(--bg); border: 1px solid var(--border); padding: 0.25rem 0.5rem; border-radius: 0.25rem;">${d.word}</span>`).join("")),a.classList.remove("hidden")}catch{r.textContent="Could not find words. Please try again.",r.classList.remove("hidden")}finally{e.disabled=!1,e.textContent="Find Synonyms"}}}e.addEventListener("click",l);m.addEventListener("keypress",n=>{n.key==="Enter"&&l()});
